nce_url":"https://data.bibliotheken.nl/id/nbt/p296471801","review_batch":"nl-scale-20261102-031","review_status":"approved","bound_language":"dut","card_cover_url":null,"bound_author_id":987300009},"before_row":null},{"key":{"native_identity_key":"nlscale:20261102:ol:OL554751W"},"seq":12,"relation":"works","after_row":{"id":987130003,"title":"Mistress of the Empire","cover_id":null,"author_id":987304014,"work_type":"novel","source_type":"open_library","open_library_id":"OL554751W","first_publish_year":1993,"native_identity_key":"nlscale:20261102:ol:OL554751W"},"before_row":null},{"key":{"open_library_edition_id":"OL15084722M"},"seq":13,"relation":"editions","after_row":{"id":987230003,"title":"Vrouwe van het Keizerrijk","isbn_10":null,"isbn_13":"9789022537329","work_id":987130003,"cover_id":null,"language":"dut","publisher":"Mynx","publish_date":null,"open_library_edition_id":"OL15084722M"},"before_row":null},{"key":{"work_id":987130003,"language":"nl"},"seq":14,"relation":"catalog_work_descriptions","after_row":{"text":"Mara van Acoma denkt een veiligere positie te hebben bereikt wanneer een aanslag haar bestaan opnieuw ontwricht. Haar zoektocht naar de verantwoordelijken botst met de macht van het genootschap van magiërs. Om haar familie te beschermen moet ze verder kijken dan de politieke regels die ze tot dan toe heeft gebruikt. Oude vijanden en nieuwe bondgenoten maken haar keuzes ingewikkeld. De strijd raakt niet alleen haar eigen toekomst, maar ook de verhoudingen binnen het keizerrijk.","work_id":987130003,"evidence":[{"note":"Dutchhardcover9789022537329 confirmed by KBp304038377+p255788037 and exactISBNretailer. Both RaymondEFeist and JannyWurts are authors; no synthetic combinedperson. Original1993 is independently confirmed; sourceprinting2007 vs retailer2009 is unresolved printing date, not originalyear. Distinct final volume of Empiretrilogy, not omnibus.","type":"reviewed_identity_and_bibliography","sources":["https://data.bibliotheken.nl/id/nbt/p30403